import context from '../../../../context.json'

describe('Path restrictions', () => {
  it('rejects ".." segments in the request path', () => {
    cy.request({
      url: `/api/document/${encodeURIComponent('../modules/config.xqm')}`,
      failOnStatusCode: false
    }).its('status').should('eq', 400)
  })

  it('rejects ".." segments in query parameters', () => {
    cy.request({
      url: '/api/collection',
      qs: { path: '../../system' },
      failOnStatusCode: false
    }).its('status').should('eq', 400)
  })

  it('does not load documents outside the data collections', () => {
    // the app's package descriptor is readable by guest, but outside the data collections
    cy.request({
      url: `/api/parts/${encodeURIComponent(`/db/apps/${context.pkg.abbrev}/expath-pkg.xml`)}/json`,
      qs: { view: 'single' },
      failOnStatusCode: false
    }).its('status').should('eq', 404)
  })

  it('accepts search terms containing dots and percent signs', () => {
    cy.request({
      url: '/api/search',
      qs: { query: '... 100%' },
      failOnStatusCode: false
    }).its('status').should('not.eq', 400)
  })
})
